const items = $input.all();
return items.map(item => {
  const titulo = item.json.title || '';
  const desc = item.json.contentSnippet || item.json.content || item.json.summary || '';
  const esRemoto = /remoto|remote|teletrabajo|desde casa|home office/i.test(titulo + ' ' + desc);
  return {
    json: {
      titulo,
      empresa: item.json.creator || item.json.author || 'No especificado',
      enlace: item.json.link || '',
      ubicacion: esRemoto ? 'Remoto' : 'España (presencial/no confirmado)',
      descripcion: desc,
      fuente: 'Tecnoempleo'
    }
  };
});

