let jobs = [];
try {
  const body = $input.first().json;
  jobs = Array.isArray(body) ? body : (body.jobs || []);
  jobs = jobs.filter(j => j.id && j.position);
} catch (e) {
  jobs = [];
}
return jobs.map(job => {
  return {
    json: {
      titulo: job.position || job.title || '',
      empresa: job.company || 'No especificado',
      enlace: job.url || ('https://remoteok.com' + (job.slug ? '/remote-jobs/' + job.slug : '')),
      ubicacion: 'Remoto',
      descripcion: (job.description || '').replace(/<[^>]+>/g, ' '),
      fuente: 'RemoteOK'
    }
  };
});

const items = $input.all();

// 1. PALABRAS TERMINANTEMENTE PROHIBIDAS (Eliminan puestos jerárquicos o inglés avanzado excluyente)
const bannedWords = [
  'senior', 'lead', 'director', 'manager', 'jefe', 'responsable', 'principal', 'sr.', 'coordinador',
  'ingles alto', 'inglés alto', 'advanced', 'b2', 'c1', 'fluent english', 'bilingual'
];

// 2. PALABRAS OBLIGATORIAS DE NIVEL (Cualquier variante de primer empleo o perfil inicial)
const requiredLevelWords = [
  'junior', 'jr', 'trainee', 'becario', 'becaria', 'beca', 'practicas', 'prácticas', 'practicante',
  'sin experiencia', 'entry level', 'primer empleo', 'recien titulado', 'recién titulado', 
  'graduado', 'graduada', 'pasante', 'pasantia', 'pasantía', 'asistente', 'auxiliar', 'inicial'
];

// 3. PALABRAS CLAVE DE TECNOLOGÍA, AUTOMATIZACIÓN Y SOPORTE BÁSICO
const techWords = [
  'n8n', 'make', 'zapier', 'integromat', 'automatizacion', 'automatización', 'automation', 
  'workflow', 'soporte', 'programador', 'programadora', 'desarrollador', 'desarrolladora', 
  'low-code', 'low code', 'no-code', 'no code', 'it support', 'helpdesk', 'help desk',
  'api', 'json', 'webhooks', 'procesos', 'integraciones', 'integracion', 'integración'
];

const seen = new Set();
let unique = items.filter(item => {
  const enlace = item.json.enlace;
  if (!enlace || seen.has(enlace)) return false;
  seen.add(enlace);
  return true;
});

// Filtro A: Eliminar puestos pesados o inglés excluyente
unique = unique.filter(item => {
  const titulo = (item.json.titulo || '').toLowerCase();
  return !bannedWords.some(palabra => titulo.includes(palabra));
});

// Filtro B: Asegurar que la oferta sea explícitamente para arrancar
unique = unique.filter(item => {
  const texto = ((item.json.titulo || '') + ' ' + (item.json.descripcion || '')).toLowerCase();
  return requiredLevelWords.some(palabra => texto.includes(palabra));
});

// Filtro C: Validar que se trate de tecnología, soporte o automatización
unique = unique.filter(item => {
  const texto = ((item.json.titulo || '') + ' ' + (item.json.descripcion || '')).toLowerCase();
  return techWords.some(palabra => texto.includes(palabra));
});

// Limitamos a un máximo de 10 ofertas por día para cuidar la API y mantener el orden
return unique.slice(0, 10);

